#!/usr/bin/env python3
from pwn import *
import random
import itertools

def connect_to_server():
    return remote('misc.chal.csaw.io', 5000)

def get_error_count(response):
    for line in response.split('\n'):
        if "Errors:" in line:
            try:
                return int(line.split(': ')[1])
            except:
                pass
    return None

def check_bases(conn, num_bases, bases_str):
    """Send bases to the server and get the error count"""
    conn.sendline(str(num_bases).encode())
    conn.recvuntil(b"bases: ")
    conn.sendline(bases_str.encode())
    response = conn.recvuntil(b"check? ", timeout=5).decode()
    print(f"Response for {bases_str}: {response.strip()}")
    return response, get_error_count(response)

def solve_qkd(start_num=5, max_num=300):
    """Try to solve the QKD challenge with increasingly larger numbers of qubits"""
    conn = connect_to_server()

    # Skip initial prompt
    conn.recvuntil(b"check? ")

    # Try with a small number first to understand the pattern
    num_bases = start_num
    print(f"Starting with {num_bases} bases")

    # First check if all X or all Z is correct
    all_x = 'X' * num_bases
    response, errors_all_x = check_bases(conn, num_bases, all_x)

    if errors_all_x == 0:
        print(f"Lucky! All X is correct: {all_x}")
        return receive_flag(conn, num_bases, all_x)

    all_z = 'Z' * num_bases
    response, errors_all_z = check_bases(conn, num_bases, all_z)

    if errors_all_z == 0:
        print(f"Lucky! All Z is correct: {all_z}")
        return receive_flag(conn, num_bases, all_z)

    print(f"All X: {errors_all_x} errors, All Z: {errors_all_z} errors")

    # For small numbers, we can try all combinations
    if num_bases <= 10:  # Limit for brute forcing
        print(f"Trying all {2**num_bases} possible combinations for {num_bases} bases")
        for i in range(2**num_bases):
            # Convert i to a binary string of 0s and 1s, then convert 0->X and 1->Z
            binary = format(i, f'0{num_bases}b')
            bases = ''.join('X' if bit == '0' else 'Z' for bit in binary)

            response, errors = check_bases(conn, num_bases, bases)

            if errors == 0:
                print(f"Found correct bases: {bases}")
                return receive_flag(conn, num_bases, bases)
    else:
        # For larger numbers, try a more intelligent approach
        # Start with a random guess and improve it
        current_bases = ''.join(random.choice(['X', 'Z']) for _ in range(num_bases))
        response, current_errors = check_bases(conn, num_bases, current_bases)

        if current_errors == 0:
            print(f"Lucky! Random guess is correct: {current_bases}")
            return receive_flag(conn, num_bases, current_bases)

        # Try to improve by systematically flipping bases
        iteration = 0
        max_iterations = 100  # Prevent infinite loops

        while current_errors > 0 and iteration < max_iterations:
            iteration += 1
            improved = False

            # Try to flip max(1, current_errors // 2) random bases at once
            num_to_flip = max(1, current_errors // 2)
            indices_to_flip = random.sample(range(num_bases), num_to_flip)

            new_bases = list(current_bases)
            for idx in indices_to_flip:
                new_bases[idx] = 'X' if new_bases[idx] == 'Z' else 'Z'
            new_bases = ''.join(new_bases)

            print(f"Iteration {iteration}: Flipping {num_to_flip} bases, trying: {new_bases}")
            response, new_errors = check_bases(conn, num_bases, new_bases)

            if new_errors is not None and new_errors < current_errors:
                print(f"Improved! Reduced errors from {current_errors} to {new_errors}")
                current_bases = new_bases
                current_errors = new_errors
                improved = True

                if current_errors == 0:
                    print(f"Found correct bases: {current_bases}")
                    return receive_flag(conn, num_bases, current_bases)

            # If we can't improve further, try a different random approach
            if not improved and iteration % 10 == 0:
                print("No improvement for several iterations, trying a fresh random guess")
                current_bases = ''.join(random.choice(['X', 'Z']) for _ in range(num_bases))
                response, current_errors = check_bases(conn, num_bases, current_bases)

    print("Could not solve the challenge with the current approach")
    conn.close()
    return None

def receive_flag(conn, num_bases, correct_bases):
    """Send the correct bases one more time to get the flag"""
    try:
        conn.sendline(str(num_bases).encode())
        conn.recvuntil(b"bases: ")
        conn.sendline(correct_bases.encode())

        # Try to receive the flag
        final_output = conn.recvall(timeout=10).decode()
        print(f"Server response after correct bases:\n{final_output}")

        # Extract flag if present (format: flag{...})
        import re
        flag_match = re.search(r'flag{[^}]+}', final_output)
        if flag_match:
            return flag_match.group(0)
        else:
            return f"No flag found in final output: {final_output}"
    except Exception as e:
        print(f"Error while receiving flag: {e}")
        return None
    finally:
        conn.close()

if __name__ == "__main__":
    flag = solve_qkd(start_num=5)
    print(f"Flag: {flag}")
